INSERT INTO scene_questions (id, category, difficulty, scene_text, options_json, hint, source, enabled) VALUES
('SC001', '礼品礼金', 1, '项目验收在即，长期合作的供应商负责人私下递来一张购物卡，笑着说：“就是过节的一点心意，不影响验收，您放心。”', '[{"key":"a","text":"收下，反正是老供应商，验收按标准来，不影响公事。","pot":"corrupt"},{"key":"b","text":"不收卡，但让对方折算成项目里的“增值服务”补回来。","pot":"edge"},{"key":"c","text":"明确拒绝，并提醒对方这是违规送礼，验收会严格按合同执行。","pot":"clean"}]', '违规收受礼品礼金违反中央八项规定精神，“不影响验收”本身就是影响——拿了东西，标准就难再硬。', 'internal', 1),
('SC002', '采购招标', 2, '立项论证时你发现，只有 A 公司的产品“恰好”完全满足技术参数，其他厂商都差一点，而你清楚这套参数是上任按 A 公司产品量身写的。', '[{"key":"a","text":"维持参数不变，直接走单一来源采购 A 公司，省事省力。","pot":"corrupt"},{"key":"b","text":"名义上组织询价，但参数不动，等于内定 A 公司。","pot":"edge"},{"key":"c","text":"重新论证参数合理性，去掉排他性条款，真正开放竞争。","pot":"clean"}]', '为特定供应商“量身定制”参数属于规避竞争、涉嫌利益输送，违反采购与廉洁从业相关规定。', 'internal', 1),
('SC003', '宴请旅游', 1, '外包团队负责人请你吃饭，席间频频举杯，最后委婉提出：“下一期项目还想继续跟您合作，还请多关照。”', '[{"key":"a","text":"欣然应允，暗示只要“意思到位”，下期合作没问题。","pot":"corrupt"},{"key":"b","text":"饭照吃，话不说死，只说“按流程来”，让对方觉得有空间。","pot":"edge"},{"key":"c","text":"主动结账或拒绝宴请，说明合作只看能力与报价，不接受私下请托。","pot":"clean"}]', '违规接受可能影响公正履职的宴请属于违规吃喝。吃人的嘴软，含糊其辞本身就是默许。', 'internal', 1),
('SC004', '履职验收', 2, '项目赶工，供应商主动提出：“反正功能都实现了，验收文档我们帮您一起‘处理’，保证通过，您也省心。”', '[{"key":"a","text":"让供应商代写验收材料，自己只负责签字，图个清闲。","pot":"corrupt"},{"key":"b","text":"自己写主报告，但默许供应商“优化”测试用例和数据。","pot":"edge"},{"key":"c","text":"拒绝代笔，坚持亲自核验功能并如实撰写验收结论。","pot":"clean"}]', '验收造假、让被监督对象代写结论，既失职渎职又埋下质量隐患，一旦出事责任全在你。', 'internal', 1),
('SC005', '数据造假', 2, '数据标注外包方提出，可以“优化”一下人效数据，让季度报表的投入产出比更好看，领导满意、部门加分。', '[{"key":"a","text":"同意优化，报表好看最重要，反正不影响业务实质。","pot":"corrupt"},{"key":"b","text":"不直接造假，但对明显虚高的数据睁一只眼闭一只眼。","pot":"edge"},{"key":"c","text":"坚决拒绝，坚持用真实数据，必要时主动向上级说明情况。","pot":"clean"}]', '数据造假、虚报业绩违反诚实守信与如实报告义务，是典型的弄虚作假，一查必究。', 'internal', 1),
('SC006', '利益输送', 1, '云资源采购谈判中，供应商私下提出：“按采购额给您返点，直接打到您亲属账户，绝对安全，合规无忧。”', '[{"key":"a","text":"把返点打入亲属账户，认为“不是自己名下”就没事。","pot":"corrupt"},{"key":"b","text":"不直接收钱，但让对方以“合作咨询费”名义支付给亲属。","pot":"edge"},{"key":"c","text":"当场拒绝并留存证据，向上级或纪检部门报告该供应商。","pot":"clean"}]', '通过亲属账户收受回扣是典型商业贿赂，“打别人账户”改变不了受贿性质，甚至更恶劣。', 'internal', 1),
('SC007', '商业秘密', 2, '投标截止前，你收到一份匿名快递，里面是竞争对手的详细报价单，明显是有人想“帮”你。', '[{"key":"a","text":"打开研究并据此调整自家报价，认为“机会来了”。","pot":"corrupt"},{"key":"b","text":"不主动使用，但不销毁、不报告，揣在手里当“备胎”。","pot":"edge"},{"key":"c","text":"原封不动上报纪检或招投标监督部门，绝不利用。","pot":"clean"}]', '利用非法获取的商业秘密属于不正当竞争，知情不报、留存待用同样是违纪的“灰色”操作。', 'internal', 1),
('SC008', '人事关系', 2, '上级领导打电话：“某家供应商技术确实不错，这次你多关照一下，别让我为难。”', '[{"key":"a","text":"照领导意思办，直接向该供应商倾斜，反正“有领导担着”。","pot":"corrupt"},{"key":"b","text":"给个“象征性”机会，但暗中在评分上给予照顾。","pot":"edge"},{"key":"c","text":"如实说明会按制度和程序公平评审，并做好相关记录备查。","pot":"clean"}]', '领导干部违规插手干预采购是明令禁止的，“有领导担着”不成立，经办人同样要担责。', 'internal', 1),
('SC009', '津贴补贴', 2, '项目奖金分配时，你是牵头人，团队里没人会细算，“给自己多留一点，反正没人知道”这个念头闪过。', '[{"key":"a","text":"做两套账，给自己多报一块，神不知鬼不觉。","pot":"corrupt"},{"key":"b","text":"不虚报，但把团队贡献有意往自己头上多算几分。","pot":"edge"},{"key":"c","text":"按实际贡献和既定规则公开、公平分配，接受大家监督。","pot":"clean"}]', '“没人知道”是最危险的侥幸。克扣、侵占团队应得利益，是违纪也是失德。', 'internal', 1),
('SC010', '宴请旅游', 1, '供应商邀请你参加“技术考察”，行程单上除了半天参观，剩下五天都是三亚的酒店和景点。', '[{"key":"a","text":"愉快前往，反正是对方出钱，“考察”只是名目。","pot":"corrupt"},{"key":"b","text":"婉拒全程，但同意让供应商承担往返和住宿“考察”费用。","pot":"edge"},{"key":"c","text":"拒绝此类变相旅游，如确有需要，按规定由本单位审批并承担费用。","pot":"clean"}]', '以考察之名行旅游之实，属于变相公款旅游、接受可能影响公正履职的安排，违反中央八项规定精神。', 'internal', 1),
('SC011', '履职验收', 1, '验收时发现几处功能缺陷，供应商拍胸脯：“小问题，先签了，我们后面保证补上。”', '[{"key":"a","text":"直接签字通过，反正是“小问题”，后面补不补再说。","pot":"corrupt"},{"key":"b","text":"签字但口头约定限期整改，不写入验收记录。","pot":"edge"},{"key":"c","text":"拒签，将缺陷书面记录并要求整改完成后再验收。","pot":"clean"}]', '“先签后补”往往“签了就没了”。验收放水是失职，口头承诺不落纸等于没有约束。', 'internal', 1),
('SC012', '履职验收', 2, '你发现外包团队报上来的工作量明显虚高，但“大家都这样”，前任也这么默许过来了。', '[{"key":"a","text":"默许虚报，甚至配合在确认单上签字，大家心照不宣。","pot":"corrupt"},{"key":"b","text":"不签字但也不纠正，装作没看见，维持现状。","pot":"edge"},{"key":"c","text":"核实真实工作量，坚决核减虚报部分，并向相关负责人说明。","pot":"clean"}]', '“大家都这样”不能成为违纪理由。对虚报失察、默许，属于监督失职，可能被认定为共谋。', 'internal', 1),
('SC013', '利益输送', 2, '供应商提出：“我们有一笔‘咨询费’，按合规流程走，直接打到您亲属账户，您放心。”', '[{"key":"a","text":"答应下来，认为“合规流程”四个字就是护身符。","pot":"corrupt"},{"key":"b","text":"不拒绝，但先“观望”，等供应商把流程“做漂亮”了再收。","pot":"edge"},{"key":"c","text":"识破这是变相利益输送，明确拒绝并远离。","pot":"clean"}]', '“合规流程”是行贿话术，绕过本人收受亲属账户财物，本质仍是受贿，且是处心积虑的隐蔽形式。', 'internal', 1),
('SC014', '履职验收', 3, '项目结算时，你发现财务系统里有一笔费用重复计了，金额不小，而财务尚未察觉。', '[{"key":"a","text":"默不作声，事后想办法把多出的钱“处理”到自己的渠道。","pot":"corrupt"},{"key":"b","text":"不主动揭发，但也不动这笔钱，等它自己“过去”。","pot":"edge"},{"key":"c","text":"立即指出重复计费，主动纠正，避免国有资产损失。","pot":"clean"}]', '发现差错不纠正、甚至想据为己有，性质从失察滑向侵占，一念之差就是违纪与犯罪的界线。', 'internal', 1),
('SC015', '商业秘密', 2, '手头能导出大量客户数据，你觉得“脱敏了应该没事”，想拿来做自己接的私活项目。', '[{"key":"a","text":"直接导出使用，认为脱敏后“谁也查不出来”。","pot":"corrupt"},{"key":"b","text":"只导出“看起来”不敏感的字段，自认为安全。","pot":"edge"},{"key":"c","text":"严守数据权限，不因私利触碰任何客户数据，涉及使用一律走合规审批。","pot":"clean"}]', '违规使用、泄露数据违反数据安全与保密规定，“脱敏”不等于“安全”，一旦泄露追责到个人。', 'internal', 1),
('SC016', '采购招标', 3, '技术选型上你清楚 A 方案明显更优，但 B 厂商与你有私下的利益往来，天平在心里悄悄偏了。', '[{"key":"a","text":"在评审报告中把 B 写成更优，让“技术论证”为私利背书。","pot":"corrupt"},{"key":"b","text":"不明确偏向，但在评分细节上给 B 找“合理理由”加分。","pot":"edge"},{"key":"c","text":"如实按技术优劣与成本效益做结论，主动回避涉及利益关系的厂商。","pot":"clean"}]', '用专业话语包装利益输送，是最隐蔽也最危险的腐败。技术决策一旦夹带私货，损害的是公共利益。', 'internal', 1),
('SC017', '津贴补贴', 2, '供应商私下说：“你们团队加班辛苦，加班费我们想办法从项目里‘补贴’，别走正规流程了。”', '[{"key":"a","text":"同意让供应商以项目款名义变相发补贴。","pot":"corrupt"},{"key":"b","text":"不直接同意，但默许供应商给个别骨干“单独表示”。","pot":"edge"},{"key":"c","text":"拒绝，说明加班费应按规定由单位足额发放，不接受变相补贴。","pot":"clean"}]', '以项目款变相发放补贴，绕开财务制度，是违规发放津补贴与利益输送的叠加。', 'internal', 1),
('SC018', '礼品礼金', 1, '项目刚中标，供应商送来一套“纪念品”，包装精美，说“纯属感谢，不值钱，就是份心意”。', '[{"key":"a","text":"收下纪念品，觉得“中标是公平竞争，收点心意无所谓”。","pot":"corrupt"},{"key":"b","text":"先收下，等看清价值再决定是否退回。","pot":"edge"},{"key":"c","text":"婉拒并退回，说明廉洁纪律要求不收受供应商任何礼品。","pot":"clean"}]', '中标后收受供应商礼品，是“事后感谢”式利益输送，看似小事，实则打开了围猎的口子。', 'internal', 1),
('SC019', '采购招标', 2, '评标前一晚，某投标供应商的负责人约你“喝茶”，特意强调：“就聊聊行业趋势，绝口不提项目的事。”', '[{"key":"a","text":"赴约，交谈中有意无意透露评标关注点，换取对方“日后感谢”。","pot":"corrupt"},{"key":"b","text":"赴约但守住口风不谈标底，只当吃了顿便饭。","pot":"edge"},{"key":"c","text":"婉拒邀约，评标期间不与任何投标方私下接触，必要时向组织报告。","pot":"clean"}]', '评标期间与投标人私下接触本身即违规，“不谈标底”无法自证清白，瓜田李下必须避嫌。', 'internal', 1),
('SC020', '人事关系', 2, '年度评优，你的老同学是候选人之一，私下找到你：“咱们这么多年交情，考察材料上帮我美言几句。”', '[{"key":"a","text":"在评审中为老同学拉票、说好话，助其当选。","pot":"corrupt"},{"key":"b","text":"不拉票，但撰写考察意见时刻意放大其优点、回避缺点。","pot":"edge"},{"key":"c","text":"主动说明二人关系并回避相关评审环节，让结果经得起检验。","pot":"clean"}]', '评优评先中的人情倾斜破坏公平；考察材料失真属于弄虚作假，撰写人要负责。', 'internal', 1),
('SC021', '礼品礼金', 2, '收到一个匿名快递，里面是一箱高档水果和一张购物卡，寄件信息模糊，眼下正是你负责的项目招标敏感期。', '[{"key":"a","text":"东西留下，反正匿名寄的，查不到谁送的。","pot":"corrupt"},{"key":"b","text":"购物卡上交，水果不值钱，分给办公室同事吃了。","pot":"edge"},{"key":"c","text":"原样登记上交纪检部门或按规定报告处理，并留存证据。","pot":"clean"}]', '无法退还的礼品礼金应登记上交；分食、私留都是违规处置违纪财物，敏感期更要警惕。', 'internal', 1),
('SC022', '数据造假', 2, '上级检查组下周到，领导暗示你：“台账不够规范的地方，这两天‘完善’一下，别出纰漏。”', '[{"key":"a","text":"连夜编造、补填缺失的原始记录，做到“天衣无缝”。","pot":"corrupt"},{"key":"b","text":"凭记忆补录，但不标注补录时间，让记录看起来像当时填的。","pot":"edge"},{"key":"c","text":"如实整理现有资料，缺什么说明什么，绝不伪造原始记录。","pot":"clean"}]', '伪造、篡改工作记录是弄虚作假；补录必须注明补录，把“补”做成“原”就是造假。', 'internal', 1),
('SC023', '宴请旅游', 2, '到下属单位调研，对方安排的行程里夹着半天当地景区“体验”，门票都已买好，劝你“来都来了”。', '[{"key":"a","text":"欣然前往，公务之余“顺道”游览一番。","pot":"corrupt"},{"key":"b","text":"景区不去了，但默许对方把住宿升级到超标套房。","pot":"edge"},{"key":"c","text":"取消旅游安排，严格按公务标准和既定行程执行，超标安排一律拒绝。","pot":"clean"}]', '借公务之机游山玩水是变相公款旅游；接受超标准接待同样违反中央八项规定精神。', 'internal', 1),
('SC024', '利益输送', 3, '你的配偶听说某供应商利润可观，提出想以他人代持的方式入股其关联公司：“这是家里的事，跟你工作无关。”', '[{"key":"a","text":"默许配偶操作，认为“代持”查不到自己头上。","pot":"corrupt"},{"key":"b","text":"不搞代持，用配偶实名入股，自认为“与我无关”。","pot":"edge"},{"key":"c","text":"明确反对，向组织如实报告情况，并按制度要求回避相关业务。","pot":"clean"}]', '特定关系人在与本人职权相关的企业投资入股即违规，代持更是处心积虑的隐蔽手段，罪加一等。', 'internal', 1),
('SC025', '津贴补贴', 2, '年底会议费有结余，部门同事提议：“大家辛苦一年，把结余换成购物卡发了，也算资金合理利用。”', '[{"key":"a","text":"同意，直接按人头分发。","pot":"corrupt"},{"key":"b","text":"不直接发卡，改成开“办公用品”发票报销后分发实物。","pot":"edge"},{"key":"c","text":"结余按规定退回或结转，一分钱都不能变相发到个人手里。","pot":"clean"}]', '以任何形式套取、私分财政资金都是违规发放津补贴；换发票报销是错上加错。', 'internal', 1),
('SC026', '履职验收', 2, '你负责的项目公开招标，资格审查时发现亲弟弟任职的公司也投了标。', '[{"key":"a","text":"不声张，评审时“按程序”给自家公司打个高分。","pot":"corrupt"},{"key":"b","text":"不打高分，但也不申报，心想“只要公平打分就没事”。","pot":"edge"},{"key":"c","text":"第一时间向组织报告亲属关系，主动申请回避本项目评审。","pot":"clean"}]', '涉及亲属利害关系必须申报并回避，“我没照顾”无法自证，程序正义本身就是纪律要求。', 'internal', 1),
('SC027', '商业秘密', 2, '已离职的老同事创业，找你“叙旧”，席间开口：“把原单位的客户名单给我参考参考，就几个重点客户，绝对不说是你给的。”', '[{"key":"a","text":"把客户名单导出发给对方，觉得是“帮老朋友”。","pot":"corrupt"},{"key":"b","text":"不给文件，但口头点出几家“好说话”的重点客户。","pot":"edge"},{"key":"c","text":"明确拒绝，提醒对方名单属商业秘密，双方都有保密义务。","pot":"clean"}]', '客户名单是商业秘密，口头泄露与拷贝文件同责；“帮朋友”不能凌驾于法纪之上。', 'internal', 1),
('SC028', '礼品礼金', 1, '你参加行业协会组织的业务培训，结业时主办方给每位学员发了一份标价不菲的“纪念品”。', '[{"key":"a","text":"收下，反正人人都有，法不责众。","pot":"corrupt"},{"key":"b","text":"收下但不拆封，放在柜子里“先存着”。","pot":"edge"},{"key":"c","text":"当场拒收；如确实无法拒收，登记上交并说明情况。","pot":"clean"}]', '借培训之名发放贵重纪念品属于变相送礼，“人人都有”不是免责理由，“存着不用”也是收。', 'internal', 1),
('SC029', '采购招标', 2, '发小请吃饭，求你把他新成立的公司加进单位供应商库：“先入库，资质材料我下个月一定补齐。”', '[{"key":"a","text":"打个招呼先入库，材料后补。","pot":"corrupt"},{"key":"b","text":"不入库，但把他的公司列为“备选考察对象”优先推荐。","pot":"edge"},{"key":"c","text":"明确拒绝，告知资质齐全后按公开流程申请，一视同仁。","pot":"clean"}]', '供应商入库有刚性条件，“先入后补”破坏整个采购公平；照顾熟人就是优亲厚友。', 'internal', 1),
('SC030', '履职验收', 2, '有服务对象投诉你部门办事拖拉，上级限期答复。同事支招：“先回复‘已办结’把督办应付过去，事情再慢慢办。”', '[{"key":"a","text":"照办，回复“已办结”，实际继续搁置。","pot":"corrupt"},{"key":"b","text":"回复“正在积极推进”，实际仍压着不办。","pot":"edge"},{"key":"c","text":"如实回复办理进展和困难，承诺办理时限并抓紧落实。","pot":"clean"}]', '对组织说假话、虚假办结是弄虚作假；敷衍塞责、消极应付群众诉求同样违反工作纪律。', 'internal', 1),
('SC031', '宴请旅游', 2, '老乡聚会定在城郊一家私密性很强的私人会所，组织者说“有位做工程的老乡买单，大家尽管放开吃”，而这位老乡正在投标你们单位的项目。', '[{"key":"a","text":"照常赴约，想着“老乡聚会，不谈公事”。","pot":"corrupt"},{"key":"b","text":"赴约但坚持把自己那份 AA 转给组织者。","pot":"edge"},{"key":"c","text":"得知地点和买单人后立即退出，并提醒相关纪律要求。","pot":"clean"}]', '违规出入私人会所、接受管理服务对象买单，两条红线一起踩；“AA”也洗不脱私人会所的违规属性。', 'internal', 1),
('SC032', '人事关系', 3, '干部考察中，分管领导暗示你：“小张是我看重的人，考察材料往积极的方向写，问题就别写了。”', '[{"key":"a","text":"照领导意思美化材料，隐去群众反映的问题。","pot":"corrupt"},{"key":"b","text":"不捏造优点，但把已核实的缺点写得含糊其辞、一笔带过。","pot":"edge"},{"key":"c","text":"如实撰写考察材料，客观反映优缺点，必要时向考察组负责人说明情况。","pot":"clean"}]', '考察材料失真属于弄虚作假、欺瞒组织；把缺点“写模糊”同样是失实，考察人对材料真实性负责。', 'internal', 1) AS new ON DUPLICATE KEY UPDATE category = new.category, difficulty = new.difficulty, scene_text = new.scene_text, options_json = new.options_json, hint = new.hint, source = new.source;
INSERT INTO quiz_questions (id, category, difficulty, scene, qtype, compliant, answer_note, explain_text, basis, enabled) VALUES
('QZ001', '人情往来', 2, '同事结婚，你随礼 500 元；你结婚时，同事也回随了 500 元。', 'scenario', 1, '能随能收', '正常同事关系、有来有往、金额符合当地人情水平，属于正常礼尚往来。纪律约束的是“利用职权借机敛财”和“明显超出正常往来”，不是正常人情。', '《中国共产党纪律处分条例》第九十七条：“……收受其他明显超出正常礼尚往来的财物的，依照前款规定处理”；第一百条：“利用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的，给予警告或者严重警告处分……借机敛财或者有其他侵犯国家、集体和人民利益行为的，从重或者加重处分，直至开除党籍。”', 1),
('QZ002', '津贴补贴', 2, '中秋节前，单位工会给每名职工发了一桶油、一盒月饼。', 'scenario', 1, '能收', '符合规定的工会节日慰问属于职工正当福利。判断要点：发放主体是工会、经费来源合规、标准在规定范围内、全员普惠。', '《基层工会经费收支管理办法》（总工办发〔2017〕32 号）第八条：“逢年过节可以向全体会员发放节日慰问品。”', 1),
('QZ003', '礼品礼金', 2, '你在商场消费后参加公开抽奖，中了一部手机。', 'scenario', 1, '能收', '面向不特定社会公众、机会均等、与个人职权毫无关联的中奖所得，不属于违纪所得。关键判断点：抽奖机会是否人人平等、是否与你的职务身份挂钩。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ004', '兼职取酬', 2, '经单位批准，你利用业余时间为高校培训班授课，按标准领取讲课费 2000 元。', 'scenario', 1, '能收', '经组织批准、实际提供了劳务、报酬在标准范围内，属于合法劳动报酬。红线在于：未经批准兼职取酬、挂名不干活领酬、超出规定标准取酬。', '《中国共产党纪律处分条例》第一百零三条：“……违反有关规定在经济组织、社会组织等单位中兼职，或者经批准兼职但获取薪酬、奖金、津贴等额外利益的，依照第一款规定处理。”', 1),
('QZ005', '人情往来', 2, '老家发小（在家务农，与你的工作毫无交集）寄来两袋自家种的花生。', 'scenario', 1, '能收', '对方与你的职权、管辖范围无任何交集，物品价值微小，属于正常亲友往来。判断三问：对方是谁、图什么、值多少——三问均无红灯。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金……财物，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ006', '生活作风', 2, '国庆假期，你自费带家人旅游，入住了高档酒店。', 'scenario', 1, '可以', '花自己的钱、休假期间、不与管理服务对象同行、不影响公务，属于个人消费自由。享乐主义、奢靡之风针对的是挥霍公款或造成不良影响的消费。', '中央八项规定精神；《中国共产党纪律处分条例》第一百五十条：“生活奢靡、铺张浪费、贪图享乐、追求低级趣味，造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分。”', 1),
('QZ007', '人情往来', 2, '你孩子结婚，事前按规定向组织报备，婚宴控制在规定桌数内，来宾均为亲友、无管理服务对象，亲友们正常随礼。', 'scenario', 1, '能收', '婚丧喜庆本身可以办，违规的是不报备、超规模、邀请管理服务对象、借机敛财。做到“报备 + 控规模 + 不请管理服务对象”，正常亲友随礼可以收。', '《中国共产党纪律处分条例》第一百条：“利用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分；借机敛财……从重或者加重处分，直至开除党籍。”', 1),
('QZ008', '宴请接待', 3, '大学同学聚会，AA 制聚餐。同学中有一人是你单位的供应商，但全程叙旧、不谈业务、费用均摊。', 'scenario', 1, '可以参加', '私人情谊、自己买单、无请托事项、未影响公正执行公务，不属于违纪。但要有边界意识：聚会中不谈工作、不接受对方单独买单、事后不因私交在业务上给予关照。', '《中国共产党纪律处分条例》第一百零一条：“接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排，情节较重的，给予警告或者严重警告处分……”', 1),
('QZ009', '礼品礼金', 1, '微信群里抢了一个 8 毛钱的拼手气红包，群主是你单位的供应商，群里多为业务往来对象。', 'scenario', 0, '不能收', '电子红包是隐形变异送礼的典型形态，金额再小不改变性质——8 毛钱的背后是“试探”和“铺路”。正确做法：不抢，已抢的退回或上交。', '中央八项规定精神；《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ010', '借用财物', 1, '供应商说“公司这辆车反正闲着，你先开着用”，借给你使用半年。', 'scenario', 0, '不能借、不能用', '“借”是名义，“输送利益”是实质。借用管理和服务对象的钱款、住房、车辆等，本身就是违纪，不论是否归还、是否付油费。', '《中国共产党纪律处分条例》第九十九条：“借用管理和服务对象的钱款、住房、车辆等，可能影响公正执行公务，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务、留党察看或者开除党籍处分。”', 1),
('QZ011', '借用财物', 2, '你买房缺首付，向供应商借款 50 万，打了借条，约定按银行利率付利息。', 'scenario', 0, '不能借', '手续齐全不改变性质。向管理服务对象借贷，对方图的是你的职权，利息只是遮羞布。通过民间借贷获取大额回报、影响公正执行公务的，明令禁止。', '《中国共产党纪律处分条例》第九十九条：“……通过民间借贷等金融活动获取大额回报，可能影响公正执行公务的，依照前款规定处理。”', 1),
('QZ012', '利益输送', 2, '供应商没送一分钱，但打了个电话，帮你孩子安排进知名券商实习。', 'scenario', 0, '不能接受', '“机会”也是利益。权钱交易早已不限于现金和实物，入学、就业、就医、晋升等非物质利益同样是利益输送的常见标的。', '《中国共产党纪律处分条例》第九十四条：“利用职权或者职务上的影响为他人谋取利益，本人的配偶、子女及其配偶等亲属和其他特定关系人收受对方财物，情节较重的，给予警告或者严重警告处分……”；《刑法》第三百八十五条及受贿罪司法解释对“财产性利益”的认定。', 1),
('QZ013', '宴请接待', 2, '你自掏腰包，请管理服务对象在人均 2000 元的餐厅吃饭，联络感情。', 'scenario', 0, '不能', '谁买单不改变性质。条例同时约束“接受”和“提供”可能影响公正执行公务的宴请——你请对方，同样可能构成“提供可能影响公正执行公务的宴请”。', '《中国共产党纪律处分条例》第一百零一条：“接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务或者留党察看处分。”', 1),
('QZ014', '礼品礼金', 1, '项目验收完、款项全部结清，合作方寄来一盒茶叶，附言“感谢支持，后会有期”。', 'scenario', 0, '不能收', '“事后感谢”是围猎的常见话术。业务虽结束，但你的职务影响力仍在，对方感谢的从来不是你这个人，而是你的岗位。且“后会有期”说明对方在为下一次合作铺路。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ016', '礼品礼金', 3, '市场价 300 万的房子，供应商以 240 万“优惠价”卖给你，你签订了正规购房合同。', 'scenario', 0, '不能买（交易型受贿）', '付了钱不等于合法。以明显低于市场价格向请托人购买房屋、汽车等物品，差价部分即为受贿数额，这叫“交易型受贿”。', '《刑法》第三百八十五条：“国家工作人员利用职务上的便利，索取他人财物的，或者非法收受他人财物，为他人谋取利益的，是受贿罪。”；“两高”《关于办理受贿刑事案件适用法律若干问题的意见》：“以明显低于市场的价格向请托人购买房屋、汽车等物品的，以受贿论处。”', 1),
('QZ017', '礼品礼金', 2, '朋友送你一幅字画，说“地摊上买的，不值钱”。经鉴定，实为名家真迹，价值数十万元。', 'scenario', 0, '不能收（雅贿）', '“雅贿”按物品实际价值认定，“不知道值钱”不构成免责理由。收受字画、古董、玉石等“雅贿”，是近年通报的高频形态。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ019', '礼品礼金', 2, '你已退休三年。当年你一手提拔的老下属如今是老板，春节提着贵重节礼登门拜年。', 'scenario', 0, '不能收（期权腐败）', '退休不是“安全着陆”。离职或者退（离）休后利用原职权或职务上的影响收受财物、为他人谋利，属于“期权腐败”，照样追究党纪直至刑事责任。', '《中国共产党纪律处分条例》第一百零六条：“……离职或者退（离）休后利用原职权或者职务上的影响，为配偶、子女及其配偶等亲属和其他特定关系人从事经营活动谋取利益……依照前款规定处理。”；《刑法》第三百八十八条之一：“离职的国家工作人员……利用该离职的国家工作人员原职权或者地位形成的便利条件实施前款行为的，依照前款的规定定罪处罚。”', 1),
('QZ022', '人情往来', 3, '十年没联系的大学同学，去年刚中标你们单位的项目。今年春节他提着两瓶酒上门，说“老同学叙叙旧”。', 'scenario', 0, '不能收', '同学情谊是真的，但他现在的身份是你的管理服务对象，送礼时点又在节日前——“叙旧”与“铺路”无法切割。正确做法：情可以叙，礼不能收，当场婉拒。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金……财物，情节较轻的，给予警告或者严重警告处分……收受其他明显超出正常礼尚往来的财物的，依照前款规定处理。”', 1),
('QZ025', '人情往来', 2, '下属给你孩子的满月红包里包了 2000 元，远超当地正常随礼水平。', 'scenario', 0, '不能收', '上下级之间存在职务上的管理关系，“明显超出正常礼尚往来”的礼金即踩红线。金额是否“明显超出”，参照当地正常人情水平判断。', '《中国共产党纪律处分条例》第九十七条：“……收受其他明显超出正常礼尚往来的财物的，依照前款规定处理。”', 1),
('QZ026', '纪律处分', 1, '《中国共产党纪律处分条例》规定，对党员的纪律处分种类包括：警告、严重警告、撤销党内职务、留党察看、开除党籍。', 'statement', 1, '该说法正确', '条例规定对党员的纪律处分种类共五种：警告、严重警告、撤销党内职务、留党察看、开除党籍。', '《中国共产党纪律处分条例》第八条：“对党员的纪律处分种类：（一）警告；（二）严重警告；（三）撤销党内职务；（四）留党察看；（五）开除党籍。”', 1),
('QZ027', '纪律处分', 2, '党员受到警告处分一年内、受到严重警告处分一年半内，不得在党内提拔职务或者进一步使用。', 'statement', 1, '该说法正确', '条例明确：党员受到警告处分一年内、受到严重警告处分一年半内，不得在党内提拔职务或者进一步使用，也不得向党外组织推荐担任高于其原任职务的党外职务或者进一步使用。', '《中国共产党纪律处分条例》第十一条：“党员受到警告处分一年内、受到严重警告处分一年半内，不得在党内提拔职务或者进一步使用，也不得向党外组织推荐担任高于其原任职务的党外职务或者进一步使用。”', 1),
('QZ028', '纪律处分', 2, '留党察看处分的期限最长不得超过三年。', 'statement', 0, '该说法错误', '留党察看处分分为留党察看一年、留党察看二年，期限最长不得超过二年，不是三年。', '《中国共产党纪律处分条例》第十二条：“留党察看处分，分为留党察看一年、留党察看二年……留党察看期限最长不得超过二年。”', 1),
('QZ029', '纪律处分', 2, '党员受到开除党籍处分，三年内不得重新入党。', 'statement', 0, '该说法错误', '党员受到开除党籍处分，五年内不得重新入党，而不是三年。', '《中国共产党纪律处分条例》第十三条：“党员受到开除党籍处分，五年内不得重新入党，也不得推荐担任与其原任职务相当或者高于其原任职务的党外职务。”', 1),
('QZ030', '纪律处分', 2, '党员干部主动交代本人应当受到党纪处分的问题的，可以从轻或者减轻处分。', 'statement', 1, '该说法正确', '条例规定，主动交代本人应当受到党纪处分的问题、主动上交或者退赔违纪所得等情形，可以从轻或者减轻处分。这就是“交代从宽”。', '《中国共产党纪律处分条例》第十七条：“有下列情形之一的，可以从轻或者减轻处分：（一）主动交代本人应当受到党纪处分的问题……（五）主动上交或者退赔违纪所得……”', 1),
('QZ031', '廉洁纪律', 2, '利用职权或者职务上的影响为他人谋取利益，本人的配偶、子女及其配偶等亲属和其他特定关系人收受对方财物的，要追究该党员干部的纪律责任。', 'statement', 1, '该说法正确', '本人没拿钱不等于没事。利用职权为他人谋利，由亲属和特定关系人收受财物的，照样追究党员干部的党纪责任，情节严重的开除党籍。', '《中国共产党纪律处分条例》第九十四条：“……利用职权或者职务上的影响为他人谋取利益，本人的配偶、子女及其配偶等亲属和其他特定关系人收受对方财物，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务、留党察看或者开除党籍处分。”', 1),
('QZ032', '礼品礼金', 1, '收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节严重的，给予开除党籍处分。', 'statement', 1, '该说法正确', '条例规定：收受可能影响公正执行公务的礼品礼金等财物，情节较轻的给予警告或者严重警告处分，情节较重的给予撤销党内职务或者留党察看处分，情节严重的给予开除党籍处分。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ033', '礼品礼金', 2, '收受可能影响公正执行公务的礼品、礼金等财物，只要情节较轻，就不构成违纪。', 'statement', 0, '该说法错误', '情节较轻也要给予警告或者严重警告处分——“情节轻”只是处分档次轻，不是不违纪。', '《中国共产党纪律处分条例》第九十七条：“收受可能影响公正执行公务的礼品、礼金、消费卡（券）和有价证券、股权、其他金融产品等财物，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ034', '礼品礼金', 2, '以讲课费、课题费、咨询费等名义变相送礼的，依照违规送礼的规定处理。', 'statement', 1, '该说法正确', '向从事公务的人员及其亲属、特定关系人赠送明显超出正常礼尚往来的财物属违纪；以讲课费、课题费、咨询费等名义变相送礼的，依照该规定处理。', '《中国共产党纪律处分条例》第九十八条：“……以讲课费、课题费、咨询费等名义变相送礼的，依照前款规定处理。”', 1),
('QZ035', '借用财物', 1, '借用管理和服务对象的钱款、住房、车辆等，只要打了借条、按时归还，就不违纪。', 'statement', 0, '该说法错误', '借用管理和服务对象的钱款、住房、车辆等，可能影响公正执行公务，情节较重的即构成违纪。手续齐全、按期归还不改变“借权”性质。', '《中国共产党纪律处分条例》第九十九条：“借用管理和服务对象的钱款、住房、车辆等，可能影响公正执行公务，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务、留党察看或者开除党籍处分。”', 1),
('QZ036', '借用财物', 2, '通过民间借贷等金融活动获取大额回报，可能影响公正执行公务的，属于违纪行为。', 'statement', 1, '该说法正确', '条例明确：通过民间借贷等金融活动获取大额回报，可能影响公正执行公务的，依照借用管理服务对象财物相关规定处理。', '《中国共产党纪律处分条例》第九十九条：“……通过民间借贷等金融活动获取大额回报，可能影响公正执行公务的，依照前款规定处理。”', 1),
('QZ037', '婚丧喜庆', 2, '利用职权或者职务上的影响操办婚丧喜庆事宜，只要不收礼金，就不会被追究纪律责任。', 'statement', 0, '该说法错误', '利用职权或职务影响操办婚丧喜庆事宜，造成不良影响的即应处分，不以收礼金为前提；借机敛财的从重或者加重处分，直至开除党籍。', '《中国共产党纪律处分条例》第一百条：“利用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分；借机敛财或者有其他侵犯国家、集体和人民利益行为的，从重或者加重处分，直至开除党籍。”', 1),
('QZ038', '宴请接待', 2, '接受可能影响公正执行公务的宴请要受处分，但向别人提供这类宴请不违纪。', 'statement', 0, '该说法错误', '条例同时约束“接受”和“提供”：接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排，情节较重的都要给予处分。', '《中国共产党纪律处分条例》第一百零一条：“接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务或者留党察看处分。”', 1),
('QZ039', '私人会所', 2, '违反有关规定取得、持有、实际使用高尔夫球卡等各种消费卡（券），或者违反有关规定出入私人会所，属于违反廉洁纪律的行为。', 'statement', 1, '该说法正确', '条例规定，违反有关规定取得、持有、实际使用运动健身卡、会所和俱乐部会员卡、高尔夫球卡等各种消费卡（券），或者违反有关规定出入私人会所，情节较重的即应处分。', '《中国共产党纪律处分条例》第一百零二条：“违反有关规定取得、持有、实际使用运动健身卡、会所和俱乐部会员卡、高尔夫球卡等各种消费卡（券），或者违反有关规定出入私人会所，情节较重的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务或者留党察看处分。”', 1),
('QZ040', '经商办企', 2, '党员违反有关规定经商办企业、拥有非上市公司（企业）的股份或者证券，情节严重的，给予开除党籍处分。', 'statement', 1, '该说法正确', '违反有关规定从事营利活动（经商办企业、拥有非上市公司股份或证券、违规买卖股票、从事有偿中介等），情节严重的给予开除党籍处分。', '《中国共产党纪律处分条例》第一百零三条：“违反有关规定从事营利活动，有下列行为之一，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分：（一）经商办企业；（二）拥有非上市公司（企业）的股份或者证券……”', 1),
('QZ041', '兼职取酬', 2, '经批准在经济组织中兼职的党员干部，可以正常领取兼职单位的薪酬、奖金、津贴。', 'statement', 0, '该说法错误', '经批准兼职但获取薪酬、奖金、津贴等额外利益的，依照违规从事营利活动的规定处理。批准兼职≠批准取酬。', '《中国共产党纪律处分条例》第一百零三条：“……违反有关规定在经济组织、社会组织等单位中兼职，或者经批准兼职但获取薪酬、奖金、津贴等额外利益的，依照第一款规定处理。”', 1),
('QZ042', '离职从业', 2, '党员干部离职或者退（离）休后，违反有关规定接受原任职务管辖业务相关企业的聘用，或者个人从事相关营利活动，属于违纪。', 'statement', 1, '该说法正确', '离职或退（离）休后违反规定接受原任职务管辖的地区和业务范围内企业、中介机构的聘用，或从事相关营利活动，要受党纪处分；利用原职权影响为亲属谋利的同样追责。', '《中国共产党纪律处分条例》第一百零六条：“离职或者退（离）休后违反有关规定接受原任职务管辖的地区和业务范围内或者与原工作业务直接相关的企业和中介机构等单位的聘用，或者个人从事与原任职务管辖业务或者与原工作业务直接相关的营利活动，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ043', '公款吃喝', 1, '违反有关规定组织、参加用公款支付的宴请、娱乐、健身活动，或者用公款购买赠送礼品、消费卡（券）的，对直接责任者和领导责任者都要追究纪律责任。', 'statement', 1, '该说法正确', '用公款宴请、娱乐、健身或购买赠送礼品、消费卡（券），直接责任者和领导责任者均追责，情节严重的开除党籍。', '《中国共产党纪律处分条例》第一百一十三条：“违反有关规定组织、参加用公款支付的宴请、娱乐、健身活动，或者用公款购买赠送或者发放礼品、消费卡（券）等，对直接责任者和领导责任者，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ044', '津贴补贴', 2, '违反有关规定滥发津贴、补贴、奖金、福利的，只追究直接责任者，领导责任者不担责。', 'statement', 0, '该说法错误', '违反有关规定自定薪酬或者滥发津贴、补贴、奖金、福利等，对直接责任者和领导责任者都要追究党纪责任。', '《中国共产党纪律处分条例》第一百一十四条：“违反有关规定自定薪酬或者滥发津贴、补贴、奖金、福利等，对直接责任者和领导责任者，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ045', '公款旅游', 1, '以学习培训、考察调研、职工疗养等为名变相公款旅游，或者改变公务行程、借机旅游，属于违纪行为。', 'statement', 1, '该说法正确', '条例明确列举：公款旅游或者以学习培训、考察调研、职工疗养等为名变相公款旅游，改变公务行程借机旅游，参加所管理企业、下属单位组织的考察活动借机旅游，均属违纪。', '《中国共产党纪律处分条例》第一百一十五条：“有下列行为之一，对直接责任者和领导责任者，情节较轻的，给予警告或者严重警告处分……（一）公款旅游或者以学习培训、考察调研、职工疗养等为名变相公款旅游；（二）改变公务行程，借机旅游；（三）参加所管理企业、下属单位组织的考察活动，借机旅游。”', 1),
('QZ046', '生活纪律', 1, '生活奢靡、铺张浪费、贪图享乐、追求低级趣味，造成不良影响的，属于违反生活纪律，应受党纪处分。', 'statement', 1, '该说法正确', '生活奢靡、铺张浪费、贪图享乐、追求低级趣味，造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分。', '《中国共产党纪律处分条例》第一百五十条：“生活奢靡、铺张浪费、贪图享乐、追求低级趣味，造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分。”', 1),
('QZ047', '生活纪律', 1, '违背社会公序良俗，在公共场所、网络空间有不当言行，造成不良影响的，要受到党纪处分。', 'statement', 1, '该说法正确', '违背社会公序良俗，在公共场所、网络空间有不当言行，造成不良影响的，视情节给予警告直至开除党籍处分。网上言行同样受纪律约束。', '《中国共产党纪律处分条例》第一百五十三条：“违背社会公序良俗，在公共场所、网络空间有不当言行，造成不良影响的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ048', '八项规定', 1, '中央八项规定的内容包括：改进调查研究、精简会议活动、精简文件简报、规范出访活动、改进警卫工作、改进新闻报道、严格文稿发表、厉行勤俭节约。', 'statement', 1, '该说法正确', '这是 2012 年 12 月中央政治局审议通过的八项规定的八个方面内容，是改进工作作风、密切联系群众的切入口和动员令。', '中央八项规定（2012 年 12 月 4 日中央政治局会议审议通过）：改进调查研究、精简会议活动、精简文件简报、规范出访活动、改进警卫工作、改进新闻报道、严格文稿发表、厉行勤俭节约。', 1),
('QZ049', '八项规定', 1, '中央八项规定只针对中央政治局成员，普通党员干部不受约束。', 'statement', 0, '该说法错误', '中央八项规定从中央政治局做起，但其精神面向全党。各级党组织和全体党员、干部都要贯彻落实中央八项规定精神，违规吃喝、公款旅游等问题一样追责。', '中央八项规定精神：八项规定从中央政治局做起、要求别人做到的自己先要做到；同时其精神适用于全体党员干部，违反中央八项规定精神问题依据《中国共产党纪律处分条例》相应条款处理。', 1),
('QZ050', '兼职取酬', 2, '国有企业领导人员经批准兼任其他企业领导职务的，可以领取兼职单位的薪酬及其他收入。', 'statement', 0, '该说法错误', '规定明确：未经批准不得兼任本企业所出资企业或者其他企业、事业单位、社会团体、中介机构的领导职务；经批准兼职的，不得擅自领取薪酬及其他收入。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（六）未经批准兼任本企业所出资企业或者其他企业、事业单位、社会团体、中介机构的领导职务，或者经批准兼职的，擅自领取薪酬及其他收入。”', 1),
('QZ051', '经商办企', 2, '国有企业领导人员不得在本企业的同类经营企业、关联企业和与本企业有业务关系的企业投资入股。', 'statement', 1, '该说法正确', '规定禁止国有企业领导人员个人从事营利性经营活动和有偿中介活动，或者在本企业的同类经营企业、关联企业和与本企业有业务关系的企业投资入股。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（一）个人从事营利性经营活动和有偿中介活动，或者在本企业的同类经营企业、关联企业和与本企业有业务关系的企业投资入股。”', 1),
('QZ052', '利益输送', 2, '国有企业领导人员不得以明显低于市场的价格向请托人购买房屋、汽车等物品，或者以明显高于市场的价格向请托人出售。', 'statement', 1, '该说法正确', '以明显低于市场的价格向请托人购买、以明显高于市场的价格向请托人出售房屋汽车等物品，以及其他交易形式非法收受请托人财物，均被明令禁止。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（三）以明显低于市场的价格向请托人购买房屋、汽车等物品，或者以明显高于市场的价格向请托人出售房屋、汽车等物品，以及以其他交易形式非法收受请托人财物。”', 1),
('QZ053', '利益输送', 2, '国有企业领导人员不得委托他人投资证券、期货或者以其他委托理财名义，未实际出资而获取收益。', 'statement', 1, '该说法正确', '委托理财名义下未实际出资而获取收益，或者虽实际出资但获取收益明显高于出资应得收益的，均属利用职权谋取私利的禁止行为。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（四）委托他人投资证券、期货或者以其他委托理财名义，未实际出资而获取收益，或者虽然实际出资，但获取收益明显高于出资应得收益。”', 1),
('QZ054', '礼品礼金', 2, '国有企业领导人员不得将企业经济往来中的折扣费、中介费、佣金、礼金等据为己有或者私分。', 'statement', 1, '该说法正确', '企业经济往来中的折扣费、中介费、佣金、礼金，以及因企业行为受到有关部门和单位奖励的财物等，应当上交企业，不得据为己有或者私分。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（七）将企业经济往来中的折扣费、中介费、佣金、礼金，以及因企业行为受到有关部门和单位奖励的财物等据为己有或者私分。”', 1),
('QZ055', '离职从业', 2, '国有企业领导人员离职或者退休后五年内，不得在与原任职企业有业务关系的私营企业、外资企业和中介机构担任职务、投资入股。', 'statement', 0, '该说法错误', '规定的限制期限是离职或者退休后三年内，不是五年。三年内不得在与原任职企业有业务关系的私营企业、外资企业和中介机构担任职务、投资入股，或从事、代理与原任职企业经营业务相关的经营活动。', '《国有企业领导人员廉洁从业若干规定》第六条：“……（七）离职或者退休后三年内，在与原任职企业有业务关系的私营企业、外资企业和中介机构担任职务、投资入股，或者在上述企业或者机构从事、代理与原任职企业经营业务相关的经营活动。”', 1),
('QZ056', '亲属经商', 1, '国有企业领导人员不得利用职权为配偶、子女及其他特定关系人从事营利性经营活动提供便利条件。', 'statement', 1, '该说法正确', '规定禁止利用职权为配偶、子女及其他特定关系人从事营利性经营活动提供便利条件，也禁止领导人员之间相互为对方及其亲属经商提供便利。', '《国有企业领导人员廉洁从业若干规定》第六条：“……（三）利用职权为配偶、子女及其他特定关系人从事营利性经营活动提供便利条件；（四）利用职权相互为对方及其配偶、子女和其他特定关系人从事营利性经营活动提供便利条件。”', 1),
('QZ057', '职务消费', 2, '企业发生非政策性亏损或者拖欠职工工资期间，国有企业领导人员可以照常购买或者更换小汽车、装修办公室。', 'statement', 0, '该说法错误', '规定明确：企业发生非政策性亏损或者拖欠职工工资期间，不得购买或者更换小汽车、公务包机、装修办公室、添置高档办公设备等。', '《国有企业领导人员廉洁从业若干规定》第七条：“……（六）在企业发生非政策性亏损或者拖欠职工工资期间，购买或者更换小汽车、公务包机、装修办公室、添置高档办公设备等。”', 1),
('QZ058', '职务消费', 2, '国有企业领导人员可以在特定关系人经营的场所进行职务消费。', 'statement', 0, '该说法错误', '规定禁止在特定关系人经营的场所进行职务消费；职务消费还应控制在备案预算内，并按规定公开。', '《国有企业领导人员廉洁从业若干规定》第七条：“……（三）在特定关系人经营的场所进行职务消费。”', 1),
('QZ059', '婚丧喜庆', 1, '国有企业领导人员不得大办婚丧喜庆事宜造成不良影响，或者借机敛财。', 'statement', 1, '该说法正确', '规定将“大办婚丧喜庆事宜，造成不良影响，或者借机敛财”列为加强作风建设方面的禁止行为。', '《国有企业领导人员廉洁从业若干规定》第八条：“……（二）大办婚丧喜庆事宜，造成不良影响，或者借机敛财。”', 1),
('QZ060', '政务处分', 1, '《公职人员政务处分法》规定的政务处分种类为：警告、记过、记大过、降级、撤职、开除。', 'statement', 1, '该说法正确', '政务处分共六种：警告、记过、记大过、降级、撤职、开除，适用于所有行使公权力的公职人员。', '《中华人民共和国公职人员政务处分法》第七条：“政务处分的种类为：（一）警告；（二）记过；（三）记大过；（四）降级；（五）撤职；（六）开除。”', 1),
('QZ061', '政务处分', 2, '公职人员受到记大过处分的，处分期间为十二个月。', 'statement', 0, '该说法错误', '记大过的处分期间是十八个月。各处分的期间为：警告六个月、记过十二个月、记大过十八个月、降级与撤职二十四个月。', '《中华人民共和国公职人员政务处分法》第八条：“政务处分的期间为：（一）警告，六个月；（二）记过，十二个月；（三）记大过，十八个月；（四）降级、撤职，二十四个月。政务处分决定自作出之日起生效，政务处分期自政务处分决定生效之日起计算。”', 1),
('QZ062', '政务处分', 2, '公职人员受到降级、撤职处分的，处分期间为二十四个月。', 'statement', 1, '该说法正确', '降级、撤职的处分期间为二十四个月；政务处分期自政务处分决定生效之日起计算。', '《中华人民共和国公职人员政务处分法》第八条：“政务处分的期间为：（一）警告，六个月；（二）记过，十二个月；（三）记大过，十八个月；（四）降级、撤职，二十四个月。”', 1),
('QZ063', '礼品礼金', 2, '公职人员收受可能影响公正行使公权力的礼品、礼金、有价证券等财物的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。', 'statement', 1, '该说法正确', '这是政务处分法对收受可能影响公正行使公权力财物的处分规定；向公职人员及其特定关系人赠送此类财物，或接受、提供可能影响公正行使公权力的宴请、旅游等安排，同样要受处分。', '《中华人民共和国公职人员政务处分法》第三十四条：“收受可能影响公正行使公权力的礼品、礼金、有价证券等财物的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。”', 1),
('QZ064', '经商办企', 2, '公职人员违反规定从事或者参与营利性活动，或者违反规定兼任职务、领取报酬，情节严重的，予以开除。', 'statement', 1, '该说法正确', '违反规定从事或参与营利性活动、违规兼任职务领取报酬的，予以警告、记过或记大过；情节较重的予以降级或撤职；情节严重的予以开除。', '《中华人民共和国公职人员政务处分法》第三十六条：“违反规定从事或者参与营利性活动，或者违反规定兼任职务、领取报酬的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除。”', 1),
('QZ065', '政务处分', 2, '公职人员参与赌博的，一律予以开除。', 'statement', 0, '该说法错误', '参与赌博的，视情节予以警告、记过、记大过直至降级、撤职、开除，并非一律开除；但组织赌博的，予以撤职或者开除。', '《中华人民共和国公职人员政务处分法》第四十条：“有下列行为之一的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除：……（三）参与赌博的……吸食、注射毒品，组织赌博，组织、支持、参与卖淫、嫖娼、色情淫乱活动的，予以撤职或者开除。”', 1),
('QZ066', '亲属经商', 2, '公职人员纵容、默许特定关系人利用本人职权或者职务上的影响谋取私利的，要受到政务处分。', 'statement', 1, '该说法正确', '纵容、默许特定关系人利用本人职权或职务影响谋取私利的，予以警告、记过或记大过；情节较重的予以降级或撤职；情节严重的予以开除。', '《中华人民共和国公职人员政务处分法》第三十三条：“有下列行为之一的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除：（一）贪污贿赂的；（二）利用职权或者职务上的影响为本人或者他人谋取私利的；（三）纵容、默许特定关系人利用本人职权或者职务上的影响谋取私利的。”', 1),
('QZ067', '政务处分', 2, '国有企业管理人员在政务处分期内，可以正常晋升职务、岗位等级和职称。', 'statement', 0, '该说法错误', '国有企业管理人员在政务处分期内不得晋升职务、岗位等级和职称；其中被记过、记大过、降级、撤职的，还不得晋升薪酬待遇等级。', '《中华人民共和国公职人员政务处分法》第二十一条：“国有企业管理人员在政务处分期内，不得晋升职务、岗位等级和职称；其中，被记过、记大过、降级、撤职的，不得晋升薪酬待遇等级。”', 1),
('QZ068', '国企处分', 1, '《国有企业管理人员处分条例》规定的处分种类与公职人员政务处分一致，包括警告、记过、记大过、降级、撤职、开除。', 'statement', 1, '该说法正确', '条例规定的处分种类为警告、记过、记大过、降级、撤职、开除，处分期间分别为六个月、十二个月、十八个月、二十四个月（降级、撤职）。', '《国有企业管理人员处分条例》第七条：“处分的种类为：（一）警告；（二）记过；（三）记大过；（四）降级；（五）撤职；（六）开除。”第八条：“处分的期间为：（一）警告，六个月；（二）记过，十二个月；（三）记大过，十八个月；（四）降级、撤职，二十四个月。”', 1),
('QZ069', '国企处分', 2, '经党组织或者国家机关提名、推荐、任命，在国有控股、参股公司中履行组织、领导、管理、监督等职责的人员，属于《国有企业管理人员处分条例》的适用对象。', 'statement', 1, '该说法正确', '条例适用于国家出资企业中的公职人员，包括国有独资、全资公司企业中履职人员，以及经提名、推荐、任命、批准在国有控股、参股公司及其分支机构中履行组织、领导、管理、监督职责的人员。', '《国有企业管理人员处分条例》第二条：“本条例所称国有企业管理人员，是指国家出资企业中的下列公职人员：（一）在国有独资、全资公司、企业中履行组织、领导、管理、监督等职责的人员；（二）经党组织或者国家机关、国有独资、全资公司、企业、事业单位提名、推荐、任命、批准等，在国有控股、参股公司及其分支机构中履行组织、领导、管理、监督等职责的人员……”', 1),
('QZ070', '廉洁纪律', 3, '党员干部相互利用职权为对方亲属谋取利益搞“权权交易”，因为没有直接收钱，不构成违纪。', 'statement', 0, '该说法错误', '权权交易是隐性腐败：你为我亲属谋利、我为你亲属谋利，不收一分钱照样违纪，情节严重的开除党籍。', '《中国共产党纪律处分条例》第九十五条：“相互利用职权或者职务上的影响为对方及其配偶、子女及其配偶等亲属、身边工作人员和其他特定关系人谋取利益搞权权交易的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ071', '廉洁纪律', 2, '纵容、默许配偶、子女及其配偶等亲属、身边工作人员利用本人职权或者职务上的影响谋取私利，属于违纪。', 'statement', 1, '该说法正确', '“不知道”“没参与”不是挡箭牌——纵容、默许亲属和身边工作人员打着自己的旗号谋利，同样要被追责。', '《中国共产党纪律处分条例》第九十六条：“纵容、默许配偶、子女及其配偶等亲属、身边工作人员和其他特定关系人利用党员干部本人职权或者职务上的影响谋取私利，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ072', '廉洁纪律', 2, '党员干部的配偶不实际工作却挂名领取薪酬，党员干部知情但未予纠正的，要追究该党员干部的纪律责任。', 'statement', 1, '该说法正确', '“挂名领薪”是典型隐性腐败。亲属不实际工作而获取薪酬，或者虽实际工作但领取明显超出同职级标准薪酬，党员干部知情不纠正的，同样受处分。', '《中国共产党纪律处分条例》第九十六条：“……党员干部的配偶、子女及其配偶等亲属和其他特定关系人不实际工作而获取薪酬或者虽实际工作但领取明显超出同职级标准薪酬，党员干部知情未予纠正的，依照前款规定处理。”', 1),
('QZ073', '廉洁纪律', 2, '利用职权或者职务上的影响，为配偶、子女及其配偶等亲属在审批监管、大宗采购、工程招投标等方面谋取利益，情节严重的，给予开除党籍处分。', 'statement', 1, '该说法正确', '为亲属在审批监管、资源开发、金融信贷、大宗采购、土地使用权出让、房地产开发、工程招投标、公共财政收支等方面谋利，视情节给予警告直至开除党籍处分。', '《中国共产党纪律处分条例》第一百零四条：“利用职权或者职务上的影响，为配偶、子女及其配偶等亲属和其他特定关系人在审批监管、资源开发、金融信贷、大宗采购、土地使用权出让、房地产开发、工程招投标以及公共财政收支等方面谋取利益，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ074', '离职从业', 3, '党员领导干部离职或者退（离）休后违反有关规定担任上市公司、基金管理公司独立董事、独立监事等职务，属于违纪。', 'statement', 1, '该说法正确', '独立董事、独立监事看似“虚职”，实则是利用原职务影响力的变现渠道，离职退休后违规担任即违纪。', '《中国共产党纪律处分条例》第一百零五条：“党员领导干部离职或者退（离）休后违反有关规定担任上市公司、基金管理公司独立董事、独立监事等职务，情节较轻的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务处分；情节严重的，给予留党察看处分。”', 1),
('QZ075', '亲属经商', 3, '党员领导干部的配偶、子女违反规定在该干部管辖区域内经商办企业，本人拒不纠正的，应当辞去现任职务或者由组织调整职务；不服从的，给予撤销党内职务处分。', 'statement', 1, '该说法正确', '亲属在管辖区域内违规经商，干部本人有纠正义务：先纠正，拒不纠正就辞去职务或接受组织调整，顶着不办的给予撤销党内职务处分。', '《中国共产党纪律处分条例》第一百零七条：“党员领导干部的配偶、子女及其配偶，违反有关规定在该党员领导干部管辖的地区和业务范围内从事可能影响其公正执行公务的经营活动……该党员领导干部应当按照规定予以纠正；拒不纠正的，其本人应当辞去现任职务或者由组织予以调整职务；不辞去现任职务或者不服从组织调整职务的，给予撤销党内职务处分。”', 1),
('QZ076', '廉洁纪律', 2, '利用职权为配偶、子女等亲属吸收存款、推销金融产品、经营名贵特产类特殊资源提供帮助谋取利益的，属于违纪。', 'statement', 1, '该说法正确', '帮亲属“拉存款”“卖茶叶”“推保险”，只要动用职权或职务影响，就是为亲属谋利，按为亲属谋利条款处理。', '《中国共产党纪律处分条例》第一百零四条：“……利用职权或者职务上的影响，为配偶、子女及其配偶等亲属和其他特定关系人吸收存款、推销金融产品、经营名贵特产类特殊资源等提供帮助谋取利益的，依照前款规定处理。”', 1),
('QZ077', '工作纪律', 2, '党员领导干部对于到任前已经存在且属于其职责范围内的问题，消极回避、推卸责任，造成严重损害或者严重不良影响的，要受到党纪处分。', 'statement', 1, '该说法正确', '这就是针对“新官不理旧账”新增的条款：旧账只要落在你的职责范围内，消极回避、推卸责任就要追责。', '《中国共产党纪律处分条例》第一百三十条：“……党员领导干部对于到任前已经存在且属于其职责范围内的问题，消极回避、推卸责任，造成严重损害或者严重不良影响的，依照前款规定处理。”', 1),
('QZ078', '公款吃喝', 2, '违反规定参加用公款支付的宴请、娱乐、健身活动，参与者同样可能被追究党纪责任。', 'statement', 1, '该说法正确', '条例约束的不仅是组织者，“参加”用公款支付的宴请、娱乐、健身活动同样违纪，别以为“只是去吃了顿饭”。', '《中国共产党纪律处分条例》第一百一十三条：“违反有关规定组织、参加用公款支付的宴请、娱乐、健身活动，或者用公款购买赠送或者发放礼品、消费卡（券）等，对直接责任者和领导责任者，情节较轻的，给予警告或者严重警告处分……”', 1),
('QZ079', '公款旅游', 1, '以考察、学习、培训、研讨、招商、参展等名义变相用公款出国（境）旅游的，依照公款旅游的相关规定处理。', 'statement', 1, '该说法正确', '出国（境）名目再多，实质是公款旅游就按公款旅游处理，对直接责任者和领导责任者追责。', '《中国共产党纪律处分条例》第一百一十五条：“……以考察、学习、培训、研讨、招商、参展等名义变相用公款出国（境）旅游的，依照前款规定处理。”', 1),
('QZ080', '政务处分', 2, '公职人员主动交代本人应当受到政务处分的违法行为，并主动上交或者退赔违法所得的，可以从轻或者减轻给予政务处分。', 'statement', 1, '该说法正确', '主动交代、配合调查、检举立功、主动上交或退赔违法所得等，都是法定的从轻、减轻情节。', '《中华人民共和国公职人员政务处分法》第十一条：“公职人员有下列情形之一的，可以从轻或者减轻给予政务处分：（一）主动交代本人应当受到政务处分的违法行为的……（五）主动上交或者退赔违法所得的……”', 1),
('QZ081', '政务处分', 2, '公职人员在政务处分期内再次故意违法、应当受到政务处分的，应当从重给予政务处分。', 'statement', 1, '该说法正确', '处分期内再犯、串供、伪造隐匿毁灭证据、包庇同案人员、拒不上交或退赔违法所得等，都是法定从重情节。', '《中华人民共和国公职人员政务处分法》第十三条：“公职人员有下列情形之一的，应当从重给予政务处分：（一）在政务处分期内再次故意违法，应当受到政务处分的……（六）拒不上交或者退赔违法所得的……”', 1),
('QZ082', '群众纪律', 1, '公职人员在管理服务活动中故意刁难、吃拿卡要的，情节较重的，予以警告、记过或者记大过。', 'statement', 1, '该说法正确', '吃拿卡要、态度恶劣粗暴、违规收取摊派费用等侵犯管理服务对象利益的行为，都要受到政务处分。', '《中华人民共和国公职人员政务处分法》第三十八条：“有下列行为之一，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职：（一）违反规定向管理服务对象收取、摊派财物的；（二）在管理服务活动中故意刁难、吃拿卡要的；（三）在管理服务活动中态度恶劣粗暴，造成不良后果或者影响的……”', 1),
('QZ083', '工作纪律', 1, '公职人员在工作中有弄虚作假，误导、欺骗行为，造成不良后果或者影响的，要受到政务处分。', 'statement', 1, '该说法正确', '弄虚作假误导欺骗、形式主义官僚主义、玩忽职守贻误工作等，造成不良后果或影响的即应处分。', '《中华人民共和国公职人员政务处分法》第三十九条：“有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除：……（三）工作中有形式主义、官僚主义行为的；（四）工作中有弄虚作假，误导、欺骗行为的……”', 1),
('QZ084', '商业秘密', 2, '公职人员泄露因履行职责掌握的商业秘密、个人隐私，造成不良后果或者影响的，要受到政务处分。', 'statement', 1, '该说法正确', '履职中知悉的国家秘密、工作秘密、商业秘密、个人隐私都受法律保护，泄露并造成不良后果或影响的即应处分。', '《中华人民共和国公职人员政务处分法》第三十九条：“有下列行为之一，造成不良后果或者影响的，予以警告、记过或者记大过；情节较重的，予以降级或者撤职；情节严重的，予以开除：……（五）泄露国家秘密、工作秘密，或者泄露因履行职责掌握的商业秘密、个人隐私的。”', 1),
('QZ085', '政务处分', 1, '公职人员有其他违法行为，影响公职人员形象、损害国家和人民利益的，可以根据情节轻重给予相应政务处分。', 'statement', 1, '该说法正确', '这是兜底条款：违法行为不必被分则逐条列明，只要影响公职人员形象、损害国家和人民利益，即可给予处分。', '《中华人民共和国公职人员政务处分法》第四十一条：“公职人员有其他违法行为，影响公职人员形象，损害国家和人民利益的，可以根据情节轻重给予相应政务处分。”', 1),
('QZ086', '宴请接待', 1, '公职人员违反规定在公务接待、公务交通、会议活动、办公用房等方面超标准、超范围，情节较重的，予以警告、记过或者记大过。', 'statement', 1, '该说法正确', '公务接待、公车、会议活动、办公用房等工作生活保障超标准、超范围，情节较重的即应处分，情节严重的降级或撤职。', '《中华人民共和国公职人员政务处分法》第三十五条：“有下列行为之一，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职：……（二）违反规定，在公务接待、公务交通、会议活动、办公用房以及其他工作生活保障等方面超标准、超范围的……”', 1),
('QZ087', '公款吃喝', 1, '公职人员违反规定公款消费的，情节较重的予以警告、记过或者记大过；情节严重的，予以降级或者撤职。', 'statement', 1, '该说法正确', '违反规定公款消费与滥发津贴补贴、超标准接待并列，是政务处分法明令禁止的行为。', '《中华人民共和国公职人员政务处分法》第三十五条：“有下列行为之一，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职：（一）违反规定设定、发放薪酬或者津贴、补贴、奖金的……（三）违反规定公款消费的。”', 1),
('QZ088', '津贴补贴', 1, '违反规定设定、发放薪酬或者津贴、补贴、奖金的公职人员，同样会受到政务处分。', 'statement', 1, '该说法正确', '违规设定、发放薪酬津贴补贴奖金，情节较重的予以警告、记过或者记大过，情节严重的予以降级或者撤职。', '《中华人民共和国公职人员政务处分法》第三十五条：“有下列行为之一，情节较重的，予以警告、记过或者记大过；情节严重的，予以降级或者撤职：（一）违反规定设定、发放薪酬或者津贴、补贴、奖金的……”', 1),
('QZ089', '政务处分', 2, '公职人员二人以上共同违法的，根据各自在违法行为中所起的作用和应当承担的法律责任，分别给予政务处分。', 'statement', 1, '该说法正确', '共同违法不搞“一锅端”也不搞“法不责众”，按各自作用和法律责任分别处分。', '《中华人民共和国公职人员政务处分法》第九条：“公职人员二人以上共同违法，根据各自在违法行为中所起的作用和应当承担的法律责任，分别给予政务处分。”', 1),
('QZ090', '离职从业', 2, '国有企业领导人员离职后，可以接受本企业的关联企业或者与本企业有业务关系的企业提供的物质性利益。', 'statement', 0, '该说法错误', '规定禁止的不仅是“在职”收受：在职或者离职后接受、索取关联企业、业务关系企业以及管理和服务对象提供的物质性利益，均属禁止行为。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（二）在职或者离职后接受、索取本企业的关联企业、与本企业有业务关系的企业，以及管理和服务对象提供的物质性利益。”', 1),
('QZ091', '利益输送', 2, '国有企业领导人员不得利用企业上市或者上市公司并购、重组、定向增发等过程中的内幕消息为本人或者配偶、子女谋取利益。', 'statement', 1, '该说法正确', '利用上市、并购重组、定向增发中的内幕消息、商业秘密及企业无形资产为本人或特定关系人谋利，是明确的禁止行为。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（五）利用企业上市或者上市公司并购、重组、定向增发等过程中的内幕消息、商业秘密以及企业的知识产权、业务渠道等无形资产或者资源，为本人或者配偶、子女及其他特定关系人谋取利益。”', 1),
('QZ092', '亲属经商', 1, '国有企业领导人员不得将国有资产委托、租赁、承包给配偶、子女及其他特定关系人经营。', 'statement', 1, '该说法正确', '把国有资产交给自家人经营是利益输送的典型形态，被规定明令禁止。', '《国有企业领导人员廉洁从业若干规定》第六条：“……（二）将国有资产委托、租赁、承包给配偶、子女及其他特定关系人经营。”', 1),
('QZ093', '人事关系', 2, '国有企业领导人员按照规定应当实行任职回避和公务回避而没有回避的，属于违反廉洁从业规定的行为。', 'statement', 1, '该说法正确', '回避是刚性制度：应当任职回避、公务回避而没有回避的，本身就是违规，不以实际谋取利益为前提。', '《国有企业领导人员廉洁从业若干规定》第六条：“……（六）按照规定应当实行任职回避和公务回避而没有回避。”', 1),
('QZ094', '职务消费', 2, '国有企业领导人员可以将履行工作职责以外的个人费用列入职务消费报销。', 'statement', 0, '该说法错误', '职务消费只能用于履行工作职责；将工作职责以外的费用列入职务消费、超出备案预算消费，均属禁止行为。', '《国有企业领导人员廉洁从业若干规定》第七条：“……（一）超出报履行国有资产出资人职责的机构备案的预算进行职务消费；（二）将履行工作职责以外的费用列入职务消费。”', 1),
('QZ095', '职务消费', 2, '国有企业领导人员应当按照规定公开职务消费情况。', 'statement', 1, '该说法正确', '规定禁止“不按照规定公开职务消费情况”——职务消费公开是硬性要求，接受职工群众监督。', '《国有企业领导人员廉洁从业若干规定》第七条：“……（四）不按照规定公开职务消费情况。”', 1),
('QZ096', '数据造假', 1, '国有企业领导人员弄虚作假骗取荣誉、职务、职称、待遇或者其他利益的，违反廉洁从业规定。', 'statement', 1, '该说法正确', '弄虚作假骗取荣誉、职务、职称、待遇，被规定列为作风建设方面的第一项禁止行为。', '《国有企业领导人员廉洁从业若干规定》第八条：“……（一）弄虚作假，骗取荣誉、职务、职称、待遇或者其他利益。”', 1),
('QZ097', '亲属经商', 2, '国有企业领导人员默许、纵容配偶、子女和身边工作人员利用本人职权和地位从事可能造成不良影响的活动的，违反廉洁从业规定。', 'statement', 1, '该说法正确', '管好配偶、子女和身边工作人员是领导人员的应尽之责，默许纵容即违规。', '《国有企业领导人员廉洁从业若干规定》第八条：“……（三）默许、纵容配偶、子女和身边工作人员利用本人的职权和地位从事可能造成不良影响的活动。”', 1),
('QZ098', '公款吃喝', 1, '国有企业领导人员不得用公款支付与公务无关的娱乐活动费用。', 'statement', 1, '该说法正确', '用公款支付与公务无关的娱乐活动费用，是作风建设方面的禁止行为。', '《国有企业领导人员廉洁从业若干规定》第八条：“……（四）用公款支付与公务无关的娱乐活动费用。”', 1),
('QZ099', '亲属经商', 2, '国有企业领导人员的配偶、子女可以在本企业的关联企业投资入股，只要不告知领导本人即可。', 'statement', 0, '该说法错误', '本人的配偶、子女及其他特定关系人在本企业的关联企业、与本企业有业务关系的企业投资入股，属于防止利益冲突的禁止行为，“不告知”不免除违规属性。', '《国有企业领导人员廉洁从业若干规定》第六条：“……（一）本人的配偶、子女及其他特定关系人，在本企业的关联企业、与本企业有业务关系的企业投资入股。”', 1),
('QZ100', '纪律处分', 1, '监督执纪“四种形态”已经写入《中国共产党纪律处分条例》。', 'statement', 1, '该说法正确', '条例总则明确深化运用监督执纪“四种形态”：红脸出汗成为常态，党纪轻处分、组织调整成为大多数，重处分、重大职务调整成为少数，涉嫌犯罪追究刑事责任成为极少数。', '《中国共产党纪律处分条例》第五条：“深化运用监督执纪‘四种形态’，经常开展批评和自我批评，及时进行谈话提醒、批评教育、责令检查、诫勉，让‘红红脸、出出汗’成为常态，党纪轻处分、组织调整成为违纪处理的大多数，党纪重处分、重大职务调整的成为少数，严重违纪涉嫌犯罪追究刑事责任的成为极少数。”', 1),
('QZ101', '纪律处分', 3, '党员违犯党纪应当给予警告或者严重警告处分，但具有主动交代等从轻减轻情形的，可以免予党纪处分。', 'statement', 1, '该说法正确', '应当给予警告或严重警告处分，又具有第十七条规定的从轻减轻情形之一的，可以给予批评教育、责令检查、诫勉或者组织处理，免予党纪处分。', '《中国共产党纪律处分条例》第十九条：“对于党员违犯党纪应当给予警告或者严重警告处分，但是具有本条例第十七条规定的情形之一或者本条例分则中另有规定的，可以给予批评教育、责令检查、诫勉或者组织处理，免予党纪处分。”', 1),
('QZ102', '政务处分', 2, '对公职人员的同一违法行为，监察机关和公职人员任免机关、单位可以分别重复给予政务处分和处分。', 'statement', 0, '该说法错误', '同一违法行为不得重复给予政务处分和处分，即“一事不再罚”。', '《中华人民共和国公职人员政务处分法》第十六条：“对公职人员的同一违法行为，监察机关和公职人员任免机关、单位不得重复给予政务处分和处分。”', 1),
('QZ103', '政务处分', 2, '公务员在政务处分期内，只要现实表现好，就可以晋升职务、职级。', 'statement', 0, '该说法错误', '处分期内一律不得晋升职务、职级、衔级和级别；被记过、记大过、降级、撤职的，还不得晋升工资档次。', '《中华人民共和国公职人员政务处分法》第十九条：“公务员以及参照《中华人民共和国公务员法》管理的人员在政务处分期内，不得晋升职务、职级、衔级和级别；其中，被记过、记大过、降级、撤职的，不得晋升工资档次。”', 1),
('QZ104', '廉洁纪律', 2, '收受的财物与本人职权无关、只是“明显超出正常礼尚往来”，同样构成违纪。', 'statement', 1, '该说法正确', '条例第二款堵住了“不影响公务”的借口：收受其他明显超出正常礼尚往来的财物，依照收受礼品礼金的规定处理。', '《中国共产党纪律处分条例》第九十七条：“……收受其他明显超出正常礼尚往来的财物的，依照前款规定处理。”', 1),
('QZ105', '八项规定', 2, '通过快递物流收送礼品礼金、躲进内部食堂违规吃喝等“隐形变异”问题，同样属于违反中央八项规定精神。', 'statement', 1, '该说法正确', '快递送礼、电子红包、内部食堂吃喝、“不吃公款吃老板”等都是隐形变异“四风”问题，是各级纪委通报查处重点。', '中央八项规定精神；中央纪委国家监委关于违反中央八项规定精神问题的通报口径：“快递送礼”“不吃公款吃老板”等隐形变异问题均属违反中央八项规定精神。', 1),
('QZ106', '宴请接待', 1, '“不吃公款吃老板”，接受管理服务对象安排的宴请，属于违反中央八项规定精神的问题。', 'statement', 1, '该说法正确', '老板买单不等于没花钱——花的是“权力变现”的钱。接受可能影响公正执行公务的宴请即违纪。', '中央八项规定精神；《中国共产党纪律处分条例》第一百零一条：“接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排，情节较重的，给予警告或者严重警告处分……”', 1),
('QZ107', '廉洁纪律', 1, '《中国共产党纪律处分条例》要求党员干部反对特权思想和特权现象，反对任何滥用职权、谋求私利的行为。', 'statement', 1, '该说法正确', '清正廉洁、反对特权是廉洁纪律的总纲性要求，写在廉洁纪律章节首条。', '《中国共产党纪律处分条例》第九十四条：“党员干部必须正确行使人民赋予的权力，清正廉洁，反对特权思想和特权现象，反对任何滥用职权、谋求私利的行为。”', 1),
('QZ108', '纪律处分', 1, '“惩前毖后、治病救人”是党的纪律处分工作应当遵循的原则之一。', 'statement', 1, '该说法正确', '党的纪律处分工作遵循五项原则，其中包括惩前毖后、治病救人，实行惩戒与教育相结合，做到宽严相济。', '《中国共产党纪律处分条例》第四条：“党的纪律处分工作遵循下列原则：……（五）惩前毖后、治病救人。处理违犯党纪的党组织和党员，应当实行惩戒与教育相结合，做到宽严相济。”', 1),
('QZ109', '国企处分', 1, '《国有企业管理人员处分条例》自 2024 年 9 月 1 日起施行。', 'statement', 1, '该说法正确', '该条例 2024 年 4 月 26 日国务院常务会议审议通过，2024 年 5 月 21 日公布，自 2024 年 9 月 1 日起施行。', '《国有企业管理人员处分条例》附则：“本条例自 2024 年 9 月 1 日起施行。”', 1),
('QZ110', '国企处分', 2, '《国有企业管理人员处分条例》规定的处分种类中不包括“降级”。', 'statement', 0, '该说法错误', '条例规定的处分种类为警告、记过、记大过、降级、撤职、开除，“降级”是其中之一。', '《国有企业管理人员处分条例》第七条：“处分的种类为：（一）警告；（二）记过；（三）记大过；（四）降级；（五）撤职；（六）开除。”', 1),
('QZ111', '政治纪律', 1, '在重大原则问题上不同党中央保持一致且有实际言论、行为或者造成不良后果的，要受到党纪处分。', 'statement', 1, '该说法正确', '这是政治纪律的首要条款：重大原则问题上必须与党中央保持一致，有实际言行或不良后果即应处分。', '《中国共产党纪律处分条例》第四十九条：“在重大原则问题上不同党中央保持一致且有实际言论、行为或者造成不良后果的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党察看处分；情节严重的，给予开除党籍处分。”', 1),
('QZ112', '婚丧喜庆', 2, '党员操办婚丧喜庆事宜，只要事前向组织报备了，就可以邀请管理服务对象参加。', 'statement', 0, '该说法错误', '报备不等于放行。利用职权或职务影响操办婚丧喜庆、邀请管理服务对象参加造成不良影响的，依然违纪。', '《中国共产党纪律处分条例》第一百条：“利用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的，给予警告或者严重警告处分……”', 1),
('QZ113', '经商办企', 2, '党员干部利用参与企业重组改制、定向增发、兼并投资等工作中掌握的信息买卖股票的，依照违规从事营利活动的规定处理。', 'statement', 1, '该说法正确', '利用工作中掌握的内幕信息买卖股票，或通过购买信托产品、基金等方式非正常获利，按违规从事营利活动处理。', '《中国共产党纪律处分条例》第一百零三条：“……利用参与企业重组改制、定向增发、兼并投资、土地使用权出让等工作中掌握的信息买卖股票，利用职权或者职务上的影响通过购买信托产品、基金等方式非正常获利的，依照前款规定处理。”', 1),
('QZ114', '政务处分', 2, '政务处分的种类包括警告、记过、记大过、降级、撤职、开除和留用察看。', 'statement', 0, '该说法错误', '政务处分只有六种：警告、记过、记大过、降级、撤职、开除，没有“留用察看”。', '《中华人民共和国公职人员政务处分法》第七条：“政务处分的种类为：（一）警告；（二）记过；（三）记大过；（四）降级；（五）撤职；（六）开除。”', 1),
('QZ115', '利益输送', 2, '国有企业领导人员以略低于市场的价格向请托人购买物品，只要差价不大就不违规。', 'statement', 0, '该说法错误', '禁止的是“明显低于”市场价格的交易，差价背后往往是权力对价；是否“明显”结合折扣幅度、交易背景综合判断，心存侥幸讨价还价照样踩线。', '《国有企业领导人员廉洁从业若干规定》第五条：“……（三）以明显低于市场的价格向请托人购买房屋、汽车等物品，或者以明显高于市场的价格向请托人出售房屋、汽车等物品，以及以其他交易形式非法收受请托人财物。”', 1),
('QZ116', '公款旅游', 1, '国有企业领导人员不得用公款旅游或者变相旅游。', 'statement', 1, '该说法正确', '用公款旅游或者变相旅游，是职务消费方面的明确禁止行为。', '《国有企业领导人员廉洁从业若干规定》第七条：“……（五）用公款旅游或者变相旅游。”', 1),
('QZ117', '政务处分', 2, '公职人员有两个以上违法行为的，应当分别确定政务处分；应当给予两种以上政务处分的，执行其中最重的政务处分。', 'statement', 1, '该说法正确', '多个违法行为分别确定处分、合并执行：应当给予撤职以下多个相同政务处分的，可以在一个处分期以上、多个处分期之和以下确定，最长不超过四十八个月。', '《中华人民共和国公职人员政务处分法》第十五条：“公职人员有两个以上违法行为的，应当分别确定政务处分。应当给予两种以上政务处分的，执行其中最重的政务处分；应当给予撤职以下多个相同政务处分的，可以在一个政务处分期以上、多个政务处分期之和以下确定政务处分期，但是最长不得超过四十八个月。”', 1),
('QZ118', '纪律处分', 2, '党员违纪受处分后，又被发现其受处分前还有未交代的其他违纪问题的，应当从重或者加重处分。', 'statement', 1, '该说法正确', '藏着掖着过不了关：受处分后又被发现处分前未交代的问题，属于应当从重或者加重处分的情形。', '《中国共产党纪律处分条例》第二十条：“有下列情形之一的，应当从重或者加重处分：……（四）违纪受处分后，又被发现其受处分前没有交代的其他应当受到党纪处分的问题……”', 1),
('QZ119', '纪律处分', 3, '二人以上共同故意违纪的，对为首者从重处分；对其他成员按照其在共同违纪中所起的作用和应负的责任分别给予处分。', 'statement', 1, '该说法正确', '共同违纪追责到每个人：为首者从重，其他成员按所起作用和应负责任分别处分，不搞“法不责众”。', '《中国共产党纪律处分条例》第二十六条：“二人以上共同故意违纪的，对为首者，从重处分，本条例另有规定的除外；对其他成员，按照其在共同违纪中所起的作用和应负的责任，分别给予处分。”', 1) AS new ON DUPLICATE KEY UPDATE category = new.category, difficulty = new.difficulty, scene = new.scene, qtype = new.qtype, compliant = new.compliant, answer_note = new.answer_note, explain_text = new.explain_text, basis = new.basis;
